WITH base AS (SELECT *, COALESCE(budget, 0) AS budget_filled FROM departments WHERE location IS NOT NULL), DepartmentsStats AS (SELECT location, dept_name, SUM(CASE WHEN location = 'Tokyo' THEN budget ELSE 0 END) AS tokyo_budget, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list FROM base GROUP BY location, dept_name) SELECT location, dept_name, tokyo_budget, dept_name_list FROM DepartmentsStats
